# pull in all our tasks from the task defs, easier to maintain, and cleaner in the long run
from client.src.client.modules.task_definitions import *

def dispatch_and_wait(api_client, implant_uuid: str, task_object, timeout: int = 60, send_as_msgpack:bool =False) -> dict:
    task_payload = task_object.to_task()
    
    if send_as_msgpack:
        print("Converting task to msgpack")
        task_payload = msgpack.packb(task_payload)

    response = api_client.post_implant_task(implant_uuid, task_payload)
    task_uuid = response.get("data", {}).get("task_uuid")
    assert task_uuid, "Failed to retrieve task_uuid from server response"

    # try 10 times to get message
    try_times = 10
    for i in range(0, try_times):
        task_dict = api_client.get_implant_task(implant_uuid = implant_uuid, task_uuid = task_uuid)

        task_response = task_dict.get("data", {}).get("task_response", None)

        if task_response is not None and "windows_error_code" in task_response:
            error_code = task_response.get("windows_error_code")            
            assert error_code == 0, f"Task failed. Expected 0, got {error_code}"
            return task_dict.get("data", {})

        time.sleep(5)
        
    pytest.fail(f"Task {task_uuid} timed out after {timeout} seconds")


@pytest.fixture(scope="module")
def target_implant(api_client):
    response = api_client.get_implants()
    implants = response.get("data", [])
    assert implants, "No active implants available for testing"
    return implants[0].get("implant_uuid")


