def test_22_sleep(api_client, target_implant):
    cmd = Sleep(implant_uuid=target_implant, sleep_time="3")
    dispatch_and_wait(api_client, target_implant, cmd)
    # Wait out the new sleep cycle briefly before next commands
    time.sleep(4)

def test_99_exit(api_client, target_implant):
    cmd = Exit(implant_uuid=target_implant)
    cmd_payload = cmd.to_task()
    
    api_client.post_implant_task(target_implant, cmd_payload)
    # Exit kills the process, so polling for a success response isn't reliable
    # Ensure it successfully posted instead.
    time.sleep(2)

def test_run_implant_tasks(api_client):
    """Orchestrates the full suite of implant tasks in a logical sequence."""
    
    # 1. Setup & Discovery
    implants = api_client.get_implants().get("data", [])
    assert implants, "No active implants for testing"
    # note - gets first implant, so this is assuming there's only one
    uuid = implants[0].get("implant_uuid")
    print(f"\n[!] Starting lifecycle test for: {uuid}")

    # 2. Strategy Tests
    print("[*] Testing Strategy configurations...")
    test_01_strat_list(api_client, uuid)
    test_02_strat_active(api_client, uuid)
    print("Not testing strat get/post at the  moment - only configured with one listener and this is known working")
    # test_03_strat_post(api_client, uuid)
    # test_04_strat_get(api_client, uuid)

    # 3. Memory Store Operations
    print("[*] Testing Memstore cycle...")
    test_05_memstore_clear(api_client, uuid)
    test_06_memstore_upload(api_client, uuid)
    test_07_memstore_list(api_client, uuid)
    test_08_memstore_download(api_client, uuid)
    test_09_memstore_delete(api_client, uuid)

    # 4. File System Operations
    print("[*] Testing File System commands...")
    test_10_ls_default(api_client, uuid)
    test_11_ls_path(api_client, uuid)
    test_12_cd_default(api_client, uuid)
    test_13_cd_path(api_client, uuid)
    test_14_file_upload_b64(api_client, uuid)
    test_15_file_upload_memstore(api_client, uuid)
    test_16_file_download(api_client, uuid)

    # 5. Execution (BOF)
    print("[*] Testing BOF execution...")
    test_17_bof_b64_no_args(api_client, uuid)
    test_18_bof_b64_with_args(api_client, uuid)
    test_19_bof_memstore(api_client, uuid)

    # 6. Cleanup & Termination
    print("[*] Testing Sleep and Exit...")
    test_22_sleep(api_client, uuid)
    
    # Exit is post-only, we don't wait for a response as the process dies
    test_99_exit(api_client, uuid)
    print("[+] test complete. Implant terminated.")
